         (area.y..area.y + area.height)
             .map(|y| {
                 (area.x..area.x + area.width)
                     .map(|x| {
                         buffer
                             .cell((x, y))
                             .unwrap()
                             .symbol()
                             .chars()
                             .next()
                             .unwrap_or(' ')
                     })
                     .collect::<String>()
             })
             .collect::<Vec<_>>()
             .join("\n")
     }

